	textAlign: 'start',
	color: '$rcx-font-titles-labels',
	borderTopWidth: 1,
	borderRightWidth: 1,
	borderBottomWidth: 1,
	borderLeftWidth: 1,
	borderTopColor: '$rcx-stroke-extra-light',
	borderRightColor: 'transparent',
